+/** Chooses a supported language (`en` or `ko`) from an Accept-Language header, or `fallback`. */
+export function pickLanguage(header, fallback = "en") {
+  if (typeof header !== "string" || !header.trim()) return fallback;
+  const choices = [];
+  for (const part of header.split(",")) {
+    const [rawTag, ...params] = part.trim().split(";");
+    const cleanTag = rawTag.trim();
+    if (!/^[a-z]{2,3}([-_][a-z0-9]{1,8})*$/i.test(cleanTag)) continue;
+    const tag = cleanTag.split(/[-_]/)[0].toLowerCase();
+    let q = 1;
+    let valid = true;
+    for (const p of params) {
+      const [k, v = ""] = p.split("=").map((s) => s.trim());
+      if (k.toLowerCase() === "q") {
+        q = Number(v);
+        if (v === "" || Number.isNaN(q) || q < 0 || q > 1) valid = false;
+      }
+    }
+    if (valid && q > 0 && LANGUAGES.includes(tag)) choices.push({ tag, q });
+  }
+  choices.sort((a, b) => b.q - a.q);
+  return choices[0]?.tag ?? fallback;
+}
